--------------------------------------------------------------------------------
-- ZOMATO DATABASE PROJECT -- SEED DATA (Phase 5: realistic dataset expansion)
--------------------------------------------------------------------------------
-- Rows 1-10 of every table are PRESERVED EXACTLY from the original V1/Phase 1
-- dataset (same IDs, same relationships) so every existing test in
-- database/tests/phase3_constraint_tests.sql and phase4_relationship_tests.sql
-- continues to pass unmodified. ORDER/PAYMENT/REVIEW status values for those
-- 10 original rows were updated from placeholder V1 values to DELIVERED/
-- SUCCESS, and SYSDATE was replaced with explicit historical dates, so they
-- fit coherently into the realistic date range added in this phase -- no
-- test depends on those specific values.
--
-- ORDER_ID / PAYMENT_ID / REVIEW_ID values 990 and 993-999 are permanently
-- RESERVED for the negative-test fixtures in the two test files above and
-- are never used by real data here.
--
-- Dataset is generated deterministically (fixed RNG seed) by a one-off
-- Python script, not stored in this repo, so the exact same seed file can
-- be reproduced. See docs/seed-data.md for full generation methodology,
-- distributions, and validation results.
--------------------------------------------------------------------------------

